import { isHookOutputPath, isPromptScriptOwnedHookOutput } from './managed-output-cleanup.js';

/**
 * Markers that identify files generated by PromptScript.
 * Ownership checks scan the first 50 lines to support long frontmatter.
 */
export const PROMPTSCRIPT_MARKERS = [
  '<!-- PromptScript',
  '# promptscript-generated:',
  '> Auto-generated by PromptScript',
] as const;

export function hasPromptScriptMarker(content: string): boolean {
  const lines = content.split(/\r?\n/).slice(0, 50);
  return lines.some((line) => PROMPTSCRIPT_MARKERS.some((marker) => line.includes(marker)));
}

export function isPromptScriptOwnedOutput(path: string, content: string): boolean {
  if (isHookOutputPath(path)) {
    return isPromptScriptOwnedHookOutput(path, content);
  }
  return hasPromptScriptMarker(content);
}
